const r=[{id:"meditation-M01",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-M03",title:"NCCIH · Meditasyon ve bilinçli farkındalık: etkililik ve güvenlik",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Halka yönelik rehber, meditasyonu sağlık hizmetinin yerine koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırma sınırlı. Beyin görüntüleri tek başına günlük hayatta sağlık faydasını göstermez.",limitation:"Bu rehber ODA’yı sınayan bir çalışma değil. Süreyi kısaltmak, gözleri açmak veya dikkati çevreye vermek güvenliği garanti etmez."},{id:"meditation-M04",title:"Farias ve diğerleri · 2020 · Meditasyon uygulamaları ve terapilerinde olumsuz deneyimler",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"6.703 kişiyi kapsayan, birbirinden farklı 83 çalışmada olumsuz deneyimler bildirildi. Birleştirilmiş görülme oranı %8,3 idi. Deneysel ve gözlemsel çalışmalardaki tahminler belirgin biçimde farklıydı.",limitation:"Tanımlar ve deneyimleri saptama yolları farklıydı. Bu oran, kısa bir uygulama seansındaki kişisel riskini göstermez. Bildirilen her olayın meditasyondan kaynaklandığı da gösterilmedi."},{id:"meditation-M05",title:"Gollwitzer ve Sheeran · 2006 · Duruma bağlı planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 katılımcıyı kapsayan 94 bağımsız sınamada, tanınabilir bir durumla belirli bir davranışı eşleştiren planlar hedefe ulaşmayı ortalama olarak destekledi.",limitation:"Hedefler ve yöntemler farklıydı. Katılımcıların çoğu üniversite öğrencisiydi. Bu bulgu ODA’nın düzeninin faydasını, en iyi meditasyon süresini veya sakinleşmeyi kanıtlamaz."},{id:"meditation-M06",title:"Gan, Zhang ve Chen · 2022 · Beden taraması meditasyonunun etkileri",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 bağımsız rastgele kontrollü çalışma makalesinde, pasif kontrollere göre bilinçli farkındalıkta küçük fark bulundu: g = 0,268, %95 güven aralığı 0,032 ile 0,504. Tek başına beden taramasının sağlık faydası hâlâ belirsiz.",limitation:"Çalışmaların kalitesi düşük, farklılıkları büyüktü. Özet, toplam katılımcı sayısını veya sağlık etkisi tahminlerini doğrulamıyor. Beden taramasının herkeste etkisiz olduğunu ya da kısa taramanın sağlık faydasını göstermez."},{id:"meditation-M07",title:"Fischer, Messner ve Pollatos · 2017 · Beden taraması sonrası bedensel sinyalleri fark etme",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2017.00452/full",type:"research",finding:"Sekiz hafta boyunca günde yirmi dakika beden taraması, 1. çalışmada kalp atımlarını saymada sesli kitaba göre istatistiksel olarak anlamlı üstünlük göstermedi. 2. çalışmada tarama, etkin olmayan kontrolden daha iyi sonuç verdi.",limitation:"Küçük öğrenci örneklemleri; sonuçlar karşılaştırılan gruba göre değişiyor. Kalp atımlarını saymak hastalığı teşhis etmez, uyuşmayı açıklamaz veya ODA’nın kısa temas alıştırmasını doğrulamaz."},{id:"meditation-M08",title:"Hasenkamp ve diğerleri · 2012 · Odaklanmış meditasyonda zihnin dalması",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Meditasyon deneyimi olan on dört kişi, MR cihazında nefese odaklanırken zihinlerinin daldığı anları işaretledi. Araştırmacılar dalmayı, bunu fark etmeyi, dikkati geri getirmeyi ve odağı sürdürmeyi modelledi.",limitation:"Küçük, keşif amaçlı bir beyin görüntüleme çalışması. Yeni başlayanlara yönelik bir müdahale değil. Beynin geliştiğini, sağlık faydasını veya ses, temas ve günlük işe geçiş uyarlamalarının etkisini göstermez."},{id:"meditation-M09",title:"Zeng ve diğerleri · 2015 · İyi dilek meditasyonu ve olumlu duygular",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 araştırma raporunda 1.759 kişi vardı. Bekleme listesiyle yapılan sekiz rastgele karşılaştırmada günlük olumlu duygularda mütevazı ortalama fayda bulundu. Birleştirilmiş g = 0,395 veya 0,392, aynı deneydeki alternatif ölçümleri kullandı.",limitation:"Bunlar aynı sonucu farklı ölçümlerle hesaplayan tahminler; enerjik ve sakin duyguların ayrı etkileri değil. Etkin karşılaştırmalar az. İyilik, ilişki gelişimi veya kişilik değişimi garanti edilmez. Yanlılık yüzdesinin paydası doğrulanmadı."},{id:"meditation-M11",title:"Fredrickson ve diğerleri · 2008 · İyi dilek atölyesi ve kişisel kaynaklar",url:"https://d1ftyfwtsv9bor.cloudfront.net/cbrt-readings/mod-6/fredrickson-open-hearts-build-lives-2008.pdf",type:"research",finding:"Programda yedi haftaya yayılan, eğitmenle yapılan altı seans ve evde dinlenen kayıtlar vardı. Olumlu duygulardaki haftalık değişim, çalışmayı bitiren 139 kişide gruplar arasında istatistiksel olarak anlamlı biçimde farklıydı.",limitation:"Aynı etki, başlangıçta atanan gruba göre ve protokole uyanlarla yapılan analizlerde anlamlı değildi. Dışlamalar ve bekleme listesiyle karşılaştırma, yorumu sınırlar. Kısa dilekler bu atölye değildir; davranışa aktarımın kanıtı da değildir."},{id:"meditation-M12",title:"Álvarez-Pérez ve diğerleri · 2022 · Mantraya dayalı meditasyon derlemesi",url:"https://doi.org/10.3390/ijerph19063380",type:"research",finding:"51 çalışma farklı mantra yöntemlerini kapsadı. Kaygı analizinde 25 çalışma ve 1.825 kişi vardı. Ortalama tahmin müdahaleyi destekliyordu; gelecekteki bir çalışma için tahmin aralığı fayda olmamasını da içeriyordu.",limitation:"Hiçbir çalışmanın genel yanlılık riski düşük değildi. Derleme Benson’ın tam yöntemini veya ODA’nın kısa kelime alıştırmasını doğrulamaz, üstünlük göstermez ya da ücretli eğitimi gerekli kılmaz."},{id:"meditation-M13",title:"Toth ve diğerleri · 2020 · Zihinde prova ve performans",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Üniversitenin yayımladığı özet, iş ve beceri provasına ilişkin 37 çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131.",limitation:"Tam yöntemler, toplam katılımcı sayısı, güven aralığı, 115 etki sayısı ve eski karşılaştırma doğrulanmadı. Kişilik değişimini, iyileşmeyi veya ODA’nın prova ile davranışı birleştiren alıştırmasının etkisini göstermez."},{id:"meditation-M14",title:"Lally ve diğerleri · 2010 · Günlük hayatta alışkanlık oluşumu",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 gönüllü, yeme, içme veya hareket davranışlarını 84 gün izledi. Uygun bulunan 39 modelde, davranışın modellenen otomatiklik düzeyinin %95’ine ulaşma süresi oldukça değişkendi.",limitation:"Gözlemsel modelleme; tahminler kısmen takip süresinin ötesine uzanıyor. Ne 21 ne 66 gün bir bitiş tarihi. Araştırma meditasyon değildi. Kaçırılan fırsatlar rastgele belirlenmediğinden analiz, ilerideki aksamaların sonuçlarını garanti edemez."},{id:"meditation-M15",title:"Simonsson ve diğerleri · 2026 · Kısa meditasyonda olumsuz deneyimler",url:"https://mental.jmir.org/2026/1/e95628/",type:"research",finding:"ABD ve Birleşik Krallık’tan 5.049 yetişkin, kısa uygulamalara veya olağan internet kullanımına rastgele atandı. Meditasyonda internete göre saptanabilir ek sıkıntı görülmedi: OR 1,05, %95 güven aralığı 0,76 ile 1,47.",limitation:"Yine de sıkıntı yaşayanlar vardı. Genel %4,1 bütün grupları kapsar; yalnız meditasyonu değil. Bu ikincil analiz eşit riski, tekrarların güvenliğini veya meditasyona özgü bir süre etkisini kanıtlamaz."},{id:"meditation-M16",title:"Harvard Health · 2011 · Benson’ın gevşeme yanıtı",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Uygulayıcı rehberi, sessiz bir yerde rahat oturmayı, kişiye uygun kelime, ses, cümle veya duayı tekrarlamayı ve düşünce araya girince geri dönmeyi anlatır. Önerisi günde on ile yirmi dakikaydı.",limitation:"Blog yazısı ve kişisel anlatı; etkililik deneyi değil. Ayaklardan yüze doğru tam yönergeler, nefes verme sırası, aynı kelimeyi bir hafta kullanma şartı, dinî ve din dışı eşit etki ya da sınanmış kısa sürüm doğrulanmadı."},{id:"meditation-M17",title:"Plum Village · Yürüyüş meditasyonu",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Geleneksel rehber ayakların yere temasına ve olağan nefese dikkat verir. Adımları nefesle eşleştirmek isteğe bağlıdır, rahat ritmi izler. Dikkat çevreyi de kapsayabilir.",limitation:"Uygulama rehberi; tek başına etkililik deneyi veya en iyi süreyi gösteren kanıt değil. Gözler açık, tehlikeler öncelikli olsun. ODA’nın oturarak ve kısa seçenekleri birer uyarlama."},{id:"meditation-M18",title:"Sharon Salzberg · Lovingkindness kitabının sayfası",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Yazarın sayfası, iyi dilek meditasyonunun Budist geleneğindeki kökenini gösterir ve kısa iyi dileklere yer verir.",limitation:"Kitabın içeriği ve tam metinler incelenmedi. Sayfa her cümleyi veya dilek yöneltilen kişilerin sırasını doğrulamaz; klinik etkiyi de göstermez. ODA’nın sözleri ve isteğe bağlı kişi seçimi uyarlamadır."},{id:"meditation-M19",title:"David Treleaven · Travmaya duyarlı bilinçli farkındalık",url:"https://davidtreleaven.com/",type:"guidance",finding:"Eğitimci, dikkati uzun süre içe vermenin geçmişi yeniden yaşama, sıkıntı ve gerçeklikten kopma dâhil travmatik stresi harekete geçirebileceği konusunda uyarır.",limitation:"Ana sayfa ve uygulayıcı yaklaşımı; etkililik deneyi değil. Riskin sıklığını veya gözleri açık tutma, süreyi kısaltma ya da çevreye odaklanma gibi belirli değişikliklerin zararı önlediğini göstermez."},{id:"meditation-M20",title:"Joe Dispenza · Kendin Olma Alışkanlığını Kırmak · yayınevinin içindekiler sayfası",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Yayınevinin içindekiler sayfasında fark etme, dile getirme, teslim olma, yeniden yönlendirme ve yaratma veya prova aşamalarını içeren dört haftalık bir sıra var.",limitation:"Kitabın içeriği incelenmedi. Markalı programın veya ODA’nın birleşik prova alıştırmasının kontrollü doğrulaması bulunmadı. Planlama ve iş provası kanıtları kuantum, genetik, iyileşme veya kişilik iddialarını doğrulamaz."},{id:"meditation-M21",title:"Kral ve diğerleri · 2022 · MBSR sonrası yapısal beyin değişikliği saptanmaması",url:"https://doi.org/10.1126/sciadv.abk3316",type:"research",finding:"İki rastgele kontrollü çalışmada, meditasyona yeni başlayan 218 kişi yapısal beyin taramalarını tamamladı. Sekiz haftalık MBSR, kontrollere göre gri madde hacmi, yoğunluğu veya beyin kabuğu kalınlığında saptanabilir değişiklik yaratmadı.",limitation:"Bu bulgu, yapının kesin olarak yeniden düzenleneceği iddiasına karşıdır. İşlevsel değişiklik veya klinik fayda olmadığını göstermez. ODA’yı da sınamaz."},{id:"meditation-goyal",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-body-scan",title:"Gan, Zhang ve Chen · 2022 · Beden taraması meditasyonunun etkileri",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 bağımsız rastgele kontrollü çalışma makalesinde, pasif kontrollere göre bilinçli farkındalıkta küçük fark bulundu: g = 0,268, %95 güven aralığı 0,032 ile 0,504. Tek başına beden taramasının sağlık faydası hâlâ belirsiz.",limitation:"Çalışmaların kalitesi düşük, farklılıkları büyüktü. Özet, toplam katılımcı sayısını veya sağlık etkisi tahminlerini doğrulamıyor. Beden taramasının herkeste etkisiz olduğunu ya da kısa taramanın sağlık faydasını göstermez."},{id:"meditation-lovingkindness",title:"Zeng ve diğerleri · 2015 · İyi dilek meditasyonu ve olumlu duygular",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 araştırma raporunda 1.759 kişi vardı. Bekleme listesiyle yapılan sekiz rastgele karşılaştırmada günlük olumlu duygularda mütevazı ortalama fayda bulundu. Birleştirilmiş g = 0,395 veya 0,392, aynı deneydeki alternatif ölçümleri kullandı.",limitation:"Bunlar aynı sonucu farklı ölçümlerle hesaplayan tahminler; enerjik ve sakin duyguların ayrı etkileri değil. Etkin karşılaştırmalar az. İyilik, ilişki gelişimi veya kişilik değişimi garanti edilmez. Yanlılık yüzdesinin paydası doğrulanmadı."},{id:"mental-practice",title:"Toth ve diğerleri · 2020 · Zihinde prova ve performans",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Üniversitenin yayımladığı özet, iş ve beceri provasına ilişkin 37 çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131.",limitation:"Tam yöntemler, toplam katılımcı sayısı, güven aralığı, 115 etki sayısı ve eski karşılaştırma doğrulanmadı. Kişilik değişimini, iyileşmeyi veya ODA’nın prova ile davranışı birleştiren alıştırmasının etkisini göstermez."},{id:"meditation-adverse",title:"Farias ve diğerleri · 2020 · Meditasyon uygulamaları ve terapilerinde olumsuz deneyimler",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"6.703 kişiyi kapsayan, birbirinden farklı 83 çalışmada olumsuz deneyimler bildirildi. Birleştirilmiş görülme oranı %8,3 idi. Deneysel ve gözlemsel çalışmalardaki tahminler belirgin biçimde farklıydı.",limitation:"Tanımlar ve deneyimleri saptama yolları farklıydı. Bu oran, kısa bir uygulama seansındaki kişisel riskini göstermez. Bildirilen her olayın meditasyondan kaynaklandığı da gösterilmedi."},{id:"meditation-nccih",title:"NCCIH · Meditasyon ve bilinçli farkındalık: etkililik ve güvenlik",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Halka yönelik rehber, meditasyonu sağlık hizmetinin yerine koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırma sınırlı. Beyin görüntüleri tek başına günlük hayatta sağlık faydasını göstermez.",limitation:"Bu rehber ODA’yı sınayan bir çalışma değil. Süreyi kısaltmak, gözleri açmak veya dikkati çevreye vermek güvenliği garanti etmez."},{id:"meditation-mind-wandering-cycle",title:"Hasenkamp ve diğerleri · 2012 · Odaklanmış meditasyonda zihnin dalması",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Meditasyon deneyimi olan on dört kişi, MR cihazında nefese odaklanırken zihinlerinin daldığı anları işaretledi. Araştırmacılar dalmayı, bunu fark etmeyi, dikkati geri getirmeyi ve odağı sürdürmeyi modelledi.",limitation:"Küçük, keşif amaçlı bir beyin görüntüleme çalışması. Yeni başlayanlara yönelik bir müdahale değil. Beynin geliştiğini, sağlık faydasını veya ses, temas ve günlük işe geçiş uyarlamalarının etkisini göstermez."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Travmaya duyarlı bilinçli farkındalık",url:"https://davidtreleaven.com/",type:"guidance",finding:"Eğitimci, dikkati uzun süre içe vermenin geçmişi yeniden yaşama, sıkıntı ve gerçeklikten kopma dâhil travmatik stresi harekete geçirebileceği konusunda uyarır.",limitation:"Ana sayfa ve uygulayıcı yaklaşımı; etkililik deneyi değil. Riskin sıklığını veya gözleri açık tutma, süreyi kısaltma ya da çevreye odaklanma gibi belirli değişikliklerin zararı önlediğini göstermez."},{id:"meditation-kabat-zinn",title:"Goyal ve diğerleri · 2014 · Psikolojik stres ve iyi oluş için meditasyon programları",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"Sağlık sorunu veya stresi olan 3.515 yetişkini kapsayan 47 rastgele kontrollü çalışma, kaygı, depresyon ve ağrıda mütevazı ortalama faydalar buldu. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim vardı.",limitation:"Bunlar eğitmenle yürütülen programlardı; ODA’nın kısa alıştırmaları değildi. Etkin tedavilere üstünlük gösterilmedi. Bu, onlarla eşit etkiyi kanıtlamaz. Bazı sonuçlar için kanıt yetersizdi."},{id:"meditation-benson",title:"Harvard Health · 2011 · Benson’ın gevşeme yanıtı",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Uygulayıcı rehberi, sessiz bir yerde rahat oturmayı, kişiye uygun kelime, ses, cümle veya duayı tekrarlamayı ve düşünce araya girince geri dönmeyi anlatır. Önerisi günde on ile yirmi dakikaydı.",limitation:"Blog yazısı ve kişisel anlatı; etkililik deneyi değil. Ayaklardan yüze doğru tam yönergeler, nefes verme sırası, aynı kelimeyi bir hafta kullanma şartı, dinî ve din dışı eşit etki ya da sınanmış kısa sürüm doğrulanmadı."},{id:"meditation-thich-nhat-hanh",title:"Plum Village · Yürüyüş meditasyonu",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Geleneksel rehber ayakların yere temasına ve olağan nefese dikkat verir. Adımları nefesle eşleştirmek isteğe bağlıdır, rahat ritmi izler. Dikkat çevreyi de kapsayabilir.",limitation:"Uygulama rehberi; tek başına etkililik deneyi veya en iyi süreyi gösteren kanıt değil. Gözler açık, tehlikeler öncelikli olsun. ODA’nın oturarak ve kısa seçenekleri birer uyarlama."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness kitabının sayfası",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Yazarın sayfası, iyi dilek meditasyonunun Budist geleneğindeki kökenini gösterir ve kısa iyi dileklere yer verir.",limitation:"Kitabın içeriği ve tam metinler incelenmedi. Sayfa her cümleyi veya dilek yöneltilen kişilerin sırasını doğrulamaz; klinik etkiyi de göstermez. ODA’nın sözleri ve isteğe bağlı kişi seçimi uyarlamadır."},{id:"dispenza-breaking-habit",title:"Joe Dispenza · Kendin Olma Alışkanlığını Kırmak · yayınevinin içindekiler sayfası",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Yayınevinin içindekiler sayfasında fark etme, dile getirme, teslim olma, yeniden yönlendirme ve yaratma veya prova aşamalarını içeren dört haftalık bir sıra var.",limitation:"Kitabın içeriği incelenmedi. Markalı programın veya ODA’nın birleşik prova alıştırmasının kontrollü doğrulaması bulunmadı. Planlama ve iş provası kanıtları kuantum, genetik, iyileşme veya kişilik iddialarını doğrulamaz."}],i=[{schemaVersion:2,revision:2,id:"meditation-1",courseId:"meditation",locale:"tr",title:"Yine daldın mı? Dikkatini bir kez geri getir.",goal:"Dikkatini rahat bir şeye bir kez geri getir. Ardından işe yarayan tek bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir dakika daha kaygıyla mı geçti? Dikkatini geri getireceğin bir şey seç, sonra yapacağın işe dön.",reason:{id:"meditation-1-reason",label:"Neye dikkat vermek istiyorsun? Dağılması sana ne kaybettiriyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Yemek planlarken yazmaya ayırdığım zaman gitti","Birinin söylediğini kaçırdım","Yararlı bir işi yarım bıraktım","Henüz böyle bir fırsat olmadı"]},why:{id:"meditation-1-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Meditasyon deneyimi olanlar da zihinlerinin daldığını fark eder. Nefese odaklanılan küçük bir çalışmada araştırmacılar dalmayı, fark etmeyi, geri dönmeyi ve odakta kalmayı izledi. Çalışma, uygulama sırasındaki dikkati anlattı. Sağlığın iyileştiğini kanıtlamadı. Bu ayrımı, zihninin tamamen susmasını beklemeden kendi denemende kullanabilirsin.","Dikkatini rahatça verebildiğin bir şey seç: olağan nefesin, bir ses veya gördüğün bir nesne. Aklının nereye gittiğini fark et, sonra bir kez geri dön. İstersen gözlerin açık kalsın. Bu kısa aradan sonra seçtiğin işte veya konuşmada işe yarayan bir adım at. Dikkatini geri getirmeyi ve yaptığın işi ayrı kaydet. İkisi için de sakin olman gerekmiyor."],example:{title:"Leyla dikkatini bir kez geri getiriyor",text:"Leyla saat 13.10’da, gönüllü ekip için bir bilgilendirme notu yazmadan önce mutfak masasına oturuyor. Odadaki bir sesi dinliyor. Akşam yemeğini planlamaya daldığını fark edip sese dönüyor. Sonra notun işe yarayan ilk cümlesini yazıyor. Dikkati yine dağılıyor. Hem sese döndüğünü hem cümleyi yazdığını kaydediyor. “Zihnim sustu” diye yazmıyor."}},move:{invitation:"Seçtiğin işi koru. Gönüllü ekibin bilgi notu örneğini kendine göre düzenle.",instructions:["Rahat bir şeye odaklan. Daldığını fark edince dikkatini geri getir.","Seçtiğin yararlı adımı at. Sonra ne olduğunu kaydet."],prompts:[],suggestions:{action:["Dikkatini geri getir; bilgi notuna ilk cümleyi yaz","Dikkatini geri getir; gönüllü çalışmasının başlama saatini sor"],minimum:["Bir kez yeniden odaklan; bilgi notuna cümle yaz","Yeniden odaklan; gönüllü çalışması hakkında bir soru sor"],cue:["Öğle yemeğinden sonra, bilgi notunu yazmadan önce","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, gözlerim açık otururken","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[2,1,3],fallback:["Gördüğün bir nesneye odaklan; bilgi notunun cümlesini yaz","Ara ver ve destek seç"],observation:["Dikkatimi geri getirdim mi; cümleyi yazdım mı","Hangi odağı rahatça kullanabildiğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Dikkatini geri getir; bilgi notuna ilk cümleyi yaz",minimum:"Bir kez yeniden odaklan; bilgi notuna cümle yaz",minutes:2,cueHint:"Öğle yemeğinden sonra, bilgi notunu yazmadan önce",placeHint:"Mutfak masasında, gözlerim açık otururken",obstacleHint:"Nefesimi izlemek bana rahatsızlık veriyor",fallbackHint:"Gördüğün bir nesneye odaklan; bilgi notunun cümlesini yaz",observationHint:"Dikkatimi geri getirdim mi; cümleyi yazdım mı"},stopRule:"Sıkıntı artarsa, başın dönerse veya gerçeklikten kopmuş hissedersen dur. Çevrene yönel. Belirtiler sürerse ya da seni kaygılandırırsa destek al.",accessibleAlternative:"Gözlerin açık kalsın. Bir ses, gördüğün bir nesne veya otururken hissettiğin teması kullan."},result:{question:"Dikkatini geri getirip seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-1-decision",scenario:"Leyla’nın bir dakikalık ses alıştırması huzursuz geçiyor ama katlanılabilir. Akşam yemeği planına daldığını fark ediyor. Bilgi notunun ilk cümlesi hâlâ yazılmayı bekliyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-1-restart",text:"Bilgi notuna başlamadan önce daha düzgün odaklanmak için bir dakikayı yeniden başlatsın.",feedback:"Baştan başlamak çekici gelebilir. Ama planladığı ara, bir odaklanma sınavı değildi. Dikkatini bir kez geri getir, planladığın gibi bitir ve işe yarayan cümleyi yaz."},{id:"meditation-1-return",text:"Sese geri dönsün, arayı bitirsin, ardından bilgi notunun ilk cümlesini yazsın.",feedback:"Bu seçim, denenen beceriyi ve amacını birlikte sınar. Huzursuz bir arada da dikkatini geri getirebilirsin. Cümle, ardından ne yaptığını gösterir. Sakinleştiğini kanıtlaması gerekmez."},{id:"meditation-1-solve",text:"Bilgi notuna başlamadan önce kalan arada akşam yemeği planını netleştirsin.",feedback:"Yemeği planlamak iş bitirmek gibi gelebilir. Ama bu denemenin amacını değiştiriyor. Gerekirse düşünceyi not et, dikkatini seçtiğin şeye geri getir ve kararlaştırdığın işi yap."}],bestOptionId:"meditation-1-return"}},carry:{takeaway:"Dikkatini geri getirmeyi dene. Sonra onu kendi seçtiğin iş için kullan.",followUp:{questionId:"meditation-1-return",question:"Dikkatini geri getirdikten sonra seçtiğin işi yaptın mı, yoksa yalnızca ara mı verdin?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Deneyimli zihinler de dalar",paragraphs:["Hasenkamp ve arkadaşları, meditasyon deneyimi olan on dört kişiyi MR cihazında yirmi dakika boyunca nefese odaklanırken inceledi. Katılımcılar burun delikleri veya üst dudak çevresindeki hislere dikkat verdi. Dikkatlerinin tamamen dağıldığını fark ettiklerinde düğmeye basıp geri döndüler. Araştırmacılar dört aşama modelledi: dalma, bunu fark etme, dikkati geri çevirme ve odağı sürdürme. Bu, tek bir görevin işleyişini anlatır. Herkesin ne kadar oturması gerektiğini belirleyen bir talimat değildir. (meditation-M08)","Beyin görüntülerindeki ilişkiler, her geri dönüşün beynini yeniden düzenlediğini, zekânı artırdığını veya sağlığını değiştirdiğini göstermez. ODA’nın sesi dinleme, gözleri açık tutma ve kısa başlangıç arası, laboratuvardaki yöntemden farklıdır. Bunları isteğe bağlı uyarlamalar olarak kullan. Kaydında bir şeye dikkat vermeyi, daldığını fark etmeyi ve geri dönmeyi ayırt et. Her düşünceyi sayman gerekmiyor. Hedef tutturmak için dikkatini bilerek dağıtmana da gerek yok."]},{heading:"Kısa aranın amacı daha sınırlı",paragraphs:["Goyal’ın derlemesinde, sağlık sorunu veya stresi olan 3.515 yetişkinle yapılmış kırk yedi rastgele kontrollü çalışma vardı. Programlarda eğitmenin hazır bulunduğu en az dört saatlik eğitim yer alıyordu. Kaygı, depresyon ve ağrı sonuçları, bazı bilinçli farkındalık programlarında ortalama olarak mütevazı düzeyde daha iyiydi. Bunlar ODA’nın bir dakikalık arası için aynı sonuçları göstermez. Derlemede etkin tedavilere üstünlük bulunmadı. Bu da o tedavilerle eşit etkiyi kanıtlamaz. (meditation-M01)","Senin denemende daha dar bir soru var: rahat bir odak seçip geri dönebilir, ardından günlük bir iş için dikkatini kullanabilir misin? ODA bu birleşimi sınamadı. İşe yarayan bir cümleyi, soruyu veya ara verme kararını sağlık iddiasına çevirmeden kaydedebilirsin. NCCIH, meditasyonu sağlık hizmetinin yerine koymama ve değerlendirmeyi geciktirmeme uyarısı yapıyor. Sana önerilen tedaviyi sürdür. Uygulama veya belirtiler seni kaygılandırıyorsa uygun destek al. (meditation-M03)"]}],sourceIds:["meditation-M08","meditation-M01","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-2",courseId:"meditation",locale:"tr",title:"Rahatsızlığı görmezden gelip devam etme",goal:"Rahat bir teması dene. İşe yarayan bir düzenleme yap, sonra seçtiğin işe dön.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Rahatsız sandalyeyi yine mi görmezden geldin? İşe yarayan bir seçim yapacak kadar dikkat et.",reason:{id:"meditation-2-reason",label:"Devam etmek için hangi ihtiyacını görmezden geliyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Rahat olmayan oturma yeri","İhtiyacım olan bir mola","Değerlendirme gerektiren ağrı","Fark ettiğim bir ihtiyaç yok"]},why:{id:"meditation-2-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Beden taramasında hisleri fark edersin. Bu, teşhis koymak değildir. Sekiz haftalık bir çalışmada beden taraması, kalp atımlarını sayma görevinde sesli kitap dinlemekten üstün çıkmadı. Başka bir karşılaştırmada, hiçbir şey yapmayan gruptan daha iyi sonuç verdi. Bu fark önemli. Bedenini fark etmek, daha iyi sağlığa götürdüğü kanıtlanmış bir kestirme yol değil.","Bunu yalnızca önceki odak sana zor geldiyse veya günlük bir ihtiyacını gözden kaçırdıysan kullan. Ellerin ve oturduğun yer gibi, rahat iki temas noktasını kısaca fark et. Belirgin bir his fark etmemek de gözlemdir. Gerekliyse işine yarayan bir düzenleme yap. Sonra daha önce seçtiğin aynı işi yap. İstersen dikkatini çevrende bir şeye vermeyi sürdürebilirsin."],example:{title:"Leyla sandalyeyi daha rahat hâle getiriyor",text:"Leyla bir sonraki bilgi notunu yazmadan önce ellerinin masaya, bedeninin sert sandalyeye temasını fark ediyor. Bir minder koyuyor, sonra işe yarayan bir cümle yazıyor. Omuzları hâlâ gergin. Yaptığı düzenlemeyi ve cümleyi kaydediyor. Tam beden taraması yapmaya söz vermiyor. Odadaki sesleri de kullanabileceği bir seçenek olarak tutuyor."}},move:{invitation:"Seçtiğin işi koru. Sandalye ve bilgi notu örneğini kendine uyarla.",instructions:["Rahat iki temas noktasını fark et veya dikkatini çevrendeki bir şeye ver.","İşe yarayan bir düzenleme yap. Sonra önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["Sandalyeyi düzenle; bilgi notuna ilk cümleyi yaz","Teması fark et; gönüllü çalışmasının başlama saatini sor"],minimum:["Rahat teması fark et; bilgi notuna cümle yaz","Teması fark et; gönüllü çalışması için soru sor"],cue:["Gönüllü ekibin bilgi notunu yazmak için oturduğumda","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, rahat bir sandalyede","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[3,2,1],fallback:["Odadaki sesleri dinle; bilgi notunun cümlesini yaz","Ara ver ve ihtiyacına uygun destek iste"],observation:["Rahatlık için düzenleme yaptım mı; cümleyi yazdım mı","Temasa odaklanmanın rahat gelip gelmediği"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sandalyeyi düzenle; bilgi notuna ilk cümleyi yaz",minimum:"Rahat teması fark et; bilgi notuna cümle yaz",minutes:3,cueHint:"Gönüllü ekibin bilgi notunu yazmak için oturduğumda",placeHint:"Mutfak masasında, rahat bir sandalyede",obstacleHint:"Temasa odaklanmak rahatsızlık vermeye başlıyor",fallbackHint:"Odadaki sesleri dinle; bilgi notunun cümlesini yaz",observationHint:"Rahatlık için düzenleme yaptım mı; cümleyi yazdım mı"},stopRule:"Sıkıntı artarsa dur. Yeni başlayan veya süren ağrı, uyuşma ya da kaygılandıran belirtiler için tıbbi değerlendirme gerekir.",accessibleAlternative:"Gözlerin açıkken odadaki sesleri kullan. Oturarak, hareket etmeden denemen yeterli."},result:{question:"Gereken değişikliği yapıp ardından önceden seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-2-decision",scenario:"Leyla masada omuzlarındaki tanıdık gerginliği fark ediyor. Ona odaklandıkça rahatsız oluyor. Bilgi notunda bir cümle hâlâ yazılmayı bekliyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-2-extend",text:"Bir düzenleme seçmeden önce gerginliği anlamak için bedeninin başka bölgelerini de tarasın.",feedback:"Daha fazla gözlem bilgi toplamak gibi gelebilir. Ama rahatsızlık artıyor ve bu alıştırma nedenini açıklayamaz. Dur veya çevrene odaklan. Ardından günlük bir çözüm seç."},{id:"meditation-2-hold",text:"Omzu gevşeyene kadar dikkatini orada tutsun, sonra bilgi notunun cümlesini yazsın.",feedback:"Gevşemeyi beklemek, başlamayı bir duyguya bağlıyor. Rahatsız eden odağı bırakabilir, ortamı düzenleyebilir ve uygunsa cümleyi yazabilirsin. Hislerinin önce değişmesi gerekmiyor."},{id:"meditation-2-adapt",text:"Odadaki seslere dönsün, sandalyeyi düzenleyip koşullar uygunsa bilgi notunun cümlesini yazsın.",feedback:"Bu seçim, rahatsızlığı dikkate alırken seçme hakkını ve işe yarayan adımı koruyor. Temas alıştırması isteğe bağlı. Hoş olmayan odağa katlanmanı veya bir hissi teşhis etmeni istemiyor."}],bestOptionId:"meditation-2-adapt"}},carry:{takeaway:"Fark ettiğin ihtiyacı dikkate al. Sonraki adımını buna göre seç.",followUp:{questionId:"meditation-2-return",question:"İşe yarayan bir düzenleme yapıp ardından seçtiğin adımı attın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Bir his, teşhis değildir",paragraphs:["Fischer ve arkadaşları, küçük öğrenci örneklemlerinde sekiz hafta boyunca günde yirmi dakika rehberli beden taramasını inceledi. Kayıt, dikkati beden bölgeleri arasında gezdiriyordu. Bütün bedene dikkat verme ve kapanış aşaması da vardı. Tam metin ve bölgelere ayrılan süreler yayımlanmadı. ODA’nın kısa temas alıştırması bir uyarlamadır. Sınanan ses kaydını baştan oluşturduğumuz anlamına gelmez. Araştırmadaki yöntemin sonuçlarını bu kısa denemeye otomatik olarak aktaramayız. (meditation-M07)","1. çalışmada kalp atımlarını saymadaki değişim, sesli kitap grubundan istatistiksel olarak anlamlı düzeyde daha büyük değildi. 2. çalışmada beden taraması, etkin olmayan karşılaştırmadan daha iyi sonuç verdi. İkisi de hastalık saptamayı, her bedensel ihtiyacı doğru yorumlamayı veya bugünkü kısa alıştırmanın sağlık etkisini göstermez. “Belirgin bir his fark etmedim”, bu denemedeki dikkati anlatır. Yeni uyuşmayı başka adla anlatmak, ağrıyı önemsememek veya tıbbi değerlendirmeyi ertelemek için kullanılmamalı. Rahatlık için düzenleme yapmakla sağlık yardımı istemek farklı ihtiyaçları karşılar."]},{heading:"Sana uyana bak. Tedavi iddiasına çevirme.",paragraphs:["Gan ve arkadaşları, tek başına beden taramasına ilişkin on dört bağımsız rastgele kontrollü çalışma makalesini derledi. Pasif kontrollere göre bilinçli farkındalıkta küçük fark bildirdiler. Çalışmaların kalitesi düşüktü, sonuçlar oldukça değişkendi. Tek başına beden taramasının sağlık faydası hâlâ belirsiz. Bu, taramanın hiç kimseye yardım etmediğinin kanıtı değil. Kısa taramanın uzun olandan daha iyi olduğunu da göstermez. Bu sınırları, kendi denemende ne olduğunu yorumlarken koru. (meditation-M06)","Senin karşılaştırman, sana uyup uymadığıyla ilgili. Temasa dikkat vermek kullanabileceğin kadar rahat mıydı? Ardından işe yarayan bir seçim yaptın mı? Aynı işi koru ki odağı değiştirmek kurs içinde ayrı bir projeye dönüşmesin. Gözleri açmak, çevreye yönelmek, bazı bölgeleri atlamak ve süreyi kısaltmak önlem seçenekleridir. Doğrulanmış travma tedavisi veya kesin koruma değildir. NCCIH, sağlık hizmetini sürdürmeyi ve değerlendirmeyi geciktirmemeyi önerir. Dürüst bir ara verme kaydı; yardım, dinlenme veya uygun başka bir ortam seçmene yol gösterebilir. (meditation-M03)"]}],sourceIds:["meditation-M07","meditation-M06","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-3",courseId:"meditation",locale:"tr",title:"Nefesi izlemek zor mu? Bir kelime dene.",goal:"Önceki odak sana zor geldiyse, seçtiğin yararlı adımdan önce nötr bir kelimeyi dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"İşi yapmak yerine nefesini kontrol edip duruyor musun? Sana nötr gelen tek bir kelime dene.",reason:{id:"meditation-3-reason",label:"Bu ara seçtiğin işi destekleyecek mi, erteleyecek mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Önceki odak zor gelince işi destekler","Sakinleşip sakinleşmediğime bakarken işi erteler","Denemeden bilemiyorum"]},why:{id:"meditation-3-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tekrarladığın kelime, dikkatin için başka bir odaktır. Daha güçlü bir komut değil. Benson’ın uygulayıcı rehberi, düşünceler araya girince seçilen kelimeye dönmeyi anlatır. Nötr bir kelime ile duanın aynı etkiyi yarattığını göstermez. Tek bir kelimeyi bir hafta boyunca kullanman gerektiğini de söylemez.","Kaydında nefes veya temasa odaklanmak zor geldiyse “burada” gibi sana uygun bir kelime dene. Nefesin doğal kalsın, bakışını zorlama. Dikkatinin dağıldığını fark edince kelimeye dön. Planladığın süre dolunca bitir ve önceden seçtiğin yararlı adımı at. Kullandığın odak zaten sana uyuyorsa onu tekrar et. Başarmış sayılmak için sakin hissetmen gerekmiyor."],example:{title:"Leyla “burada” kelimesini deniyor",text:"Leyla’nın kaydında, nefesini izlerken her nefes alışını kontrol ettiği yazıyor. Ertesi gün saat 13.10’da gözleri açık, bir dakika boyunca içinden “burada” diyor. Alışveriş düşüncesine dalınca kelimeye dönüyor. Sonra bilgi notuna bir cümle yazıyor. Kelime sakinleştirmekten çok sıradan geliyor. Bunu kaydediyor. İşe yarayan en küçük adımı yine o cümle."}},move:{invitation:"Seçtiğin işi koru. Kelime ve bilgi notu örneğini kendine göre düzenle.",instructions:["Nefesini değiştirmeden, sana uygun tek bir kelimeye geri dön.","Arayı bitir. Ardından önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["“Burada” de; bilgi notuna ilk cümleyi yaz","Odadaki sesleri dinle; gönüllü çalışmasının başlama saatini sor"],minimum:["“Burada” kelimesine dön; bilgi notunun cümlesini yaz","Dikkatini bir kez geri getir; gönüllü çalışmasını sor"],cue:["Öğle yemeğinden sonra, bilgi notunu yazmadan önce","Gönüllü sorumlusu soru sormamızı istediğinde"],place:["Mutfak masasında, gözlerim açık otururken","Gönüllü sorumlusuyla mesajlaştığımız ekranda"],minutes:[2,1,3],fallback:["Arayı bitir, ardından bilgi notunun cümlesini yaz","Arayı bitir ve destek al"],observation:["Kelimeyi kullanmak nasıldı, bilgi notunun cümlesini yazdım mı","Aradan sonra attığım işe yarayan adım"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"“Burada” de; bilgi notuna ilk cümleyi yaz",minimum:"“Burada” kelimesine dön; bilgi notunun cümlesini yaz",minutes:2,cueHint:"Öğle yemeğinden sonra, bilgi notunu yazmadan önce",placeHint:"Mutfak masasında, gözlerim açık otururken",obstacleHint:"Sakinleşip sakinleşmediğimi kontrol etmeye başlıyorum",fallbackHint:"Arayı bitir, ardından bilgi notunun cümlesini yaz",observationHint:"Kelimeyi kullanmak nasıldı, bilgi notunun cümlesini yazdım mı"},stopRule:"Sıkıntı artarsa, başın dönerse veya gerçeklikten kopmuş hissedersen dur. Çevrene yönel ve gerekirse destek al.",accessibleAlternative:"Kelime rahatsız ediyorsa bir ses veya gördüğün nesneyi seç. Gözlerin açık kalsın."},result:{question:"Planladığın arayı bitirip ardından önceden seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-3-decision",scenario:"Leyla’ya kelime nötr geliyor; kullanmak da rahatsız etmiyor. Yine de sakinleşip sakinleşmediğini kontrol ediyor. Planladığı bir dakika bitmek üzere.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-3-end",text:"Kelimeye geri dönsün, planladığı bir dakikayı bitirsin, sonra bilgi notunun cümlesini yazsın.",feedback:"Kelime, dikkatini vereceğin bir şey sağlıyor. Ruh hâlini ölçen bir sınav değil. Zamanında bitirmek işe geçmene yer bırakır. Sakinleşmeyi şart koşma; kelimenin nasıl geldiğini ve yazdığın cümleyi kaydet."},{id:"meditation-3-switch",text:"Kalan dakikada başka bir kelime deneyip daha sakinleştirici olanı bulmaya çalışsın.",feedback:"Rahatsız eden odağı değiştirmek mantıklı olabilir. Burada kelime rahatsız etmiyor. Durmadan başka kelime aramak, farklı bir soruya cevap arıyor. İşe yarayan adımın yerini ruh hâlini kontrol etmek alabilir."},{id:"meditation-3-lengthen",text:"Kelimenin sakinleştirmeye daha çok zamanı olsun diye bir dakika daha eklesin.",feedback:"Daha uzun uygulama bir seçenek. Ama burada sakinleşmek için gerekli bir süreyi gösteren kanıt yok. Yapabileceğin arayı bitir, işi yap. Başka bir denemenin faydasını sonra değerlendirebilirsin."}],bestOptionId:"meditation-3-end"}},carry:{takeaway:"Kullanabildiğin bir odak seç. Ardından yaptığın işe yarayan adımı ayrı değerlendir.",followUp:{questionId:"meditation-3-return",question:"Kelime sana uydu mu? Ardından seçtiğin adımı attın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Kelime alıştırmasının kaynağı",paragraphs:["Harvard Health’in Benson’ın gevşeme yanıtını anlatan yazısında rahat oturma, sessiz ortam, seçilen kelime, ses, cümle veya dua ve düşünceler araya girince geri dönme yer alır. Uygulayıcının önerisi günde on ile yirmi dakikadır. Bu, listedeki her adımı sınayan bir deney değil, blog yazısı ve kişisel anlatıdır. Açılan sayfa, ayaklardan yüze doğru ilerleyen tam gevşeme metnini veya zorunlu bir nefes verme sırasını doğrulamıyor. (meditation-M16)","ODA’nın daha kısa kelime denemesi, gözleri açık tutma ve nötr söz seçimi birer uyarlamadır. Bu sayfa, onların tıbbi etkisini kanıtlamaz. İnancına uyuyorsa kendi içinde dua seçebilirsin. Burada dinî ve din dışı odakların aynı etkiyi verdiğini gösteren bir karşılaştırmalı deney yok. Sayfa, aynı kelimeye bir hafta bağlı kalmanın gerekli olduğunu da ortaya koymuyor. Geçmişteki yöntemi aynen yapmak yerine sana uygunluğa ve gerçekte ne yaşadığına göre seç."]},{heading:"Mantra derlemesi bu denemeden daha geniş",paragraphs:["Álvarez-Pérez ve arkadaşları, farklı mantra uygulamalarına ilişkin elli bir çalışmayı birleştirdi. Kaygı analizinde yirmi beş çalışma ve 1.825 kişi vardı. Ortalama tahmin müdahaleyi destekliyordu. Ama gelecekteki bir çalışma için tahmin aralığı, fayda görülmemesini de içeriyordu. Hiçbir çalışmanın genel yanlılık riski düşük değildi ve takip sınırlıydı. Adı olan bir yöntem herkese çözüm diye sunulduğunda bu sınırlara dikkat etmek gerekir. (meditation-M12)","Derleme, Benson’ın tam yöntemini, bugünkü bir dakikalık kelime odağını veya başka uygulamalara üstünlüğü doğrulamaz. Bu gönüllü deneme için alışveriş veya ücretli eğitim gerekmez. Günlük hayattaki aynı işi koruyup tek bir odağı değiştir. Böylece neyi karşılaştırdığın belli kalır. Neyi kullandığını ve ardından ne yaptığını anlat. Tek bir iyi gün, gelişmeye kelimenin neden olduğunu kanıtlamaz. Uygulama hoşuna gitse de NCCIH’nin sağlık hizmetini koruma sınırı geçerlidir. (meditation-M03)"]}],sourceIds:["meditation-M16","meditation-M12","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-4",courseId:"meditation",locale:"tr",title:"Masaya geldin. Aklın hâlâ telefonda mı?",goal:"Güvenli bir geçiş sırasında dikkatini geri getir. Vardığında seçtiğin yararlı adımı at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Masaya vardın ama aklın hâlâ telefonda mı? Yoldan masaya geçerken yapacağın işe dikkatini getir.",reason:{id:"meditation-4-reason",label:"Seçtiğin işe başlamak için vardığında hangi alışkanlığı bırakacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Mesajlara ilk cümleden sonra bakmak","Konuşmadan önce telefonu kaldırmak","İşimi engelleyen alışkanlık fark etmedim"]},why:{id:"meditation-4-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yürürken dikkatini ayaklarının yere temasına ve doğal nefesine verebilirsin. Plum Village rehberinde adımları nefesle eşleştirmek bir seçenek. Zorunlu bir nefes oranı değil. Bu, özel bir sağlık etkisinin kanıtı değil, geleneksel bir uygulama tarifi. Dikkatini verdiğin şeyden önce çevrende olup bitenler gelir.","Önceki araya bir türlü yer açamıyorsan zaten yaptığın bir geçişi kullan. Gözlerin açık olsun, güvenli hızla ilerle. Teması yalnızca tehlikelere dikkat vermeni engellemediği yerde fark et. Oturarak, yerinde durarak yapılan sürüm de bir uyarlama olarak kullanılabilir. Vardığında önceden seçtiğin yararlı adımı at. Burada, ne kadar yavaş yürüdüğünü değil, işe nasıl vardığını ve başladığını deniyorsun."],example:{title:"Leyla kütüphanede işe başlıyor",text:"Leyla mutfaktaki başlama anını sık sık kaçırıyor. Bu kez her zamanki kütüphaneye geliş anını kullanmayı deniyor. Karşıya geçerken çevresine dikkat ediyor. Sessiz girişte birkaç adımda ayaklarının yere değdiğini fark ediyor. Masada telefonunu kaldırıp bilgi notuna işe yarayan bir cümle yazıyor. Daha sonra bir bildirim yine bölüyor. Gelişini ve cümleyi kaydediyor. Gün boyu dikkati hiç dağılmadı demiyor."}},move:{invitation:"Seçtiğin işi koru. Kütüphaneye geliş örneğini kendine göre düzenle.",instructions:["Gözlerin açık, çevren öncelikli olsun. Nefesin doğal kalsın.","Vardığın yerde önceden seçtiğin yararlı adımı at."],prompts:[],suggestions:{action:["Vardığında gönüllü ekibin bilgi notuna ilk cümleyi yaz","Vardığında gönüllü çalışmasının başlama saatini sor"],minimum:["Otururken teması fark et; bilgi notuna cümle yaz","Teması fark et; gönüllü çalışması için soru sor"],cue:["Kütüphanede masama vardığımda","Gönüllü ekibin kısa toplantısına geldiğimde"],place:["Kütüphanedeki yazı masasında","Rahatça erişebildiğim gönüllü ekip toplantı masasında"],minutes:[2,1,3],fallback:["Vardığında otururken hissettiğin teması fark et","Odağı bırak, dikkatini tehlikelere ver"],observation:["Kütüphaneye vardım mı, bilgi notunun cümlesini yazdım mı","Yola bağlı başlama fırsatı oluştu mu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Vardığında gönüllü ekibin bilgi notuna ilk cümleyi yaz",minimum:"Otururken teması fark et; bilgi notuna cümle yaz",minutes:2,cueHint:"Kütüphanede masama vardığımda",placeHint:"Kütüphanedeki yazı masasında",obstacleHint:"Yolda bütün dikkatimi çevreye vermem gerekiyor",fallbackHint:"Vardığında otururken hissettiğin teması fark et",observationHint:"Kütüphaneye vardım mı, bilgi notunun cümlesini yazdım mı"},stopRule:"Gözlerin açık kalsın. Tehlikeler dikkatini gerektirdiğinde odak alıştırmasını bırak. Sıkıntı veya baş dönmesi artarsa dur ve destek al.",accessibleAlternative:"Oturarak, yerinde dururken ses veya temasa odaklan. Hareket etmen gerekmiyor."},result:{question:"Gideceğin yere güvenle varıp ardından seçtiğin yararlı adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-4-decision",scenario:"Leyla’nın yolunda kalabalık yaya geçitleri var. Vardığında seçtiği yazı masası boş. Ayaklarının yere temasına dikkat vermeyi planlamıştı.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-4-count",text:"Yol boyunca adım ritmini korusun, sonra masaya geçip bilgi notunun cümlesini yazsın.",feedback:"Alıştığı ritmi sürdürmek çekici gelebilir. Ama geçitlerde dikkat gerekiyor. Saymak tehlikeleri izlemeni engellediğinde bırak. Vardığın yerde işe yarayan adımı hâlâ atabilirsin."},{id:"meditation-4-arrive",text:"Geçitlerde çevresine dikkat etsin. Varınca otururken hissettiği teması fark edip bilgi notunu yazsın.",feedback:"Bu seçim güvenliği öne alıyor, seçilen başlama anını da deniyor. Oturarak teması fark etmek bir ODA uyarlaması. Denemenin değeri daha düşük değil. Bir tedaviyle aynı etkiyi verdiği de kanıtlanmış değil."},{id:"meditation-4-relocate",text:"Yazı denemesine dönmeden önce sessiz bir park yolunu kullanabileceği zamanı beklesin.",feedback:"Park başka bir uygulamaya uygun olabilir. Ama Leyla’nın işi yapacağı yer şimdi hazır. Kusursuz yolu şart koşmak yerine vardığında güvenli biçimde durup oturarak odaklanabilir."}],bestOptionId:"meditation-4-arrive"}},carry:{takeaway:"Güvenle varmak seçtiğin işe başlamana yardım etsin. Yol, bir odaklanma sınavı değil.",followUp:{questionId:"meditation-4-return",question:"Bir yerden diğerine geçmek, seçtiğin işe başlamanı kolaylaştırdı mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Ritmi yola göre seç",paragraphs:["Plum Village’in yürüyüş rehberi, ayakların yere temasına, doğal nefese ve çevredeki dünyaya dikkat verir. Adımları rahat nefes ritmiyle eşleştirme örnekleri sunar. Bu örnekler, zorlayarak tutturman gereken nefes hedefleri değildir. Sayfa bir uygulayıcı rehberidir. Tek başına yürüyüş meditasyonunun etkisini sınayan bir deney değildir. Geleneğin manevi sözleri de tıbbi iyileşmenin kanıtı sayılmaz. Adımlara dikkat vermeyi seçerken bu sınırı koru. (meditation-M17)","ODA, kısa ve tanıdık bir geçişi ancak önceki denemende bir soruna yanıt veriyorsa kullanır. Örneğin oturarak başlamak için seçtiğin an pek oluşmuyorsa. Sessiz yollar dâhil her yerde gözlerin açık kalsın. Saymak çevreni izlemeni engelliyorsa bırak. Oturarak veya yerinde durarak odaklanmak erişim için bir uyarlamadır. Bilimsel olarak eşit etkisi gösterilmiş değildir. İşe yarayan adımı vardığın yerde at. Onu yürüyüşten veya varıştaki kısa aradan ayrı kaydet."]},{heading:"Zaten yaptığın bir geçiş, başlama anın olabilir",paragraphs:["Gollwitzer ve Sheeran’ın derlemesinde, bir durumla belirli bir davranışı eşleştiren planlara ilişkin doksan dört bağımsız sınama vardı. Bu planlar farklı alanlarda hedefe ulaşmayı ortalama olarak destekledi. Katılımcıların çoğu üniversite öğrencisiydi. Derleme, kütüphaneye geliş düzeninin etkisini göstermez. Daha sınırlı bir planlama fikrini destekler: tanıyabileceğin bir fırsat ve yapabileceğin bir davranış seç. Böylece ne zaman ne yapacağını önceden belirleyebilirsin. (meditation-M05)","“Masama vardığımda dikkatimi bir kez geri getirip işe yarayan ilk cümleyi yazacağım”, hem fırsatı hem davranışı söyler. Gideceğin yer uygun değilse ilk deneme olmuş gibi yapma. Kullanabildiğin başka bir yer seç. Kalabalık yol gerçek bir kısıt; disiplin eksikliği değil. Bu uyarlama, egzersiz araştırmalarının faydalarını kendine mal etmez veya düşüncelere daha az takılmayı vaat etmez. NCCIH sağlık hizmetini korumayı önerir; zarar araştırmasının sınırlı olduğunu belirtir. Dışarıda olmak her uygulamayı sana uygun kılmaz. (meditation-M03)"]}],sourceIds:["meditation-M17","meditation-M05","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-5",courseId:"meditation",locale:"tr",title:"Sınırın kalsın. İğneleyen sözü çıkar.",goal:"Sertlik seçtiğin işe engelse, açık bir yanıttan önce isteğe bağlı tek bir iyi dilek dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıtına bir laf sokmak üzeresin. Söylemek istediğini koru, fazladan iğneleyen sözü çıkar.",reason:{id:"meditation-5-reason",label:"Bu yanıtta hangi sınır veya işe yarayan bilgi korunmalı?",kind:"text",maxLength:160,optional:!0,suggestions:["Pazar günü görev alamam","Gerçekte ayırabildiğim saatler","Bilgi notu için gereken ayrıntı"]},why:{id:"meditation-5-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İyi dilek meditasyonu araştırmaları, kişinin bildirdiği duyguları ölçer. Günlük davranışlarında iyiliği garanti etmez. Bir derleme, çoğunlukla bekleme listeleriyle karşılaştırıldığında olumlu duygularda mütevazı ortalama faydalar buldu. Bu, kısa bir dileğin yanıtını iyileştireceğini veya bir ilişkiyi onaracağını kanıtlamaz.","Kaydında sertliğin seçtiğin işe engel olduğunu görüyorsan bu seçeneği kullan. Kendine veya güvenli, sevdiğin birine kendi isteğinle tek bir dilek sun: “Destek bulmanı dilerim.” İçinin ısınması şart değil. Ardından önceden seçtiğin yararlı adımı at. Örneğin iğnelemeden açık bir cümle gönder. Sınırın kalsın. Dilekler canını yakıyorsa atla veya dur. Güvenli olmayan biriyle iletişim kurman hiç gerekmez."],example:{title:"Leyla sınırını açık söylüyor",text:"Leyla’nın bilgi notu, ek gönüllü çalışması için yanıt gerektiriyor. Taslağında “Bunu zaten bilmen gerekirdi” var. Mutfak masasında kız kardeşi için içinden iyi bir dilekte bulunuyor. Sonra iğneleyen kısmı çıkarıp cümlesini gönderiyor: “Cumartesi görev alabilirim ama pazar gelemem.” Hâlâ kızgın. Gönderdiği sınır cümlesini kaydediyor. İlişkiyi dileğin iyileştirdiğini söylemiyor."}},move:{invitation:"Seçtiğin işi koru. Gönüllü ekibe yanıt örneğini kendine göre düzenle.",instructions:["Kendini veya güvenli bir kişiyi seç. Sıcak duygu şart değil.","Asıl bilgiyi veya sınırını koruyarak açık cümleni kullan."],prompts:[],suggestions:{action:["Sorumluya yalnızca cumartesi görev alabileceğini söyle","Kendini suçlamadan bilgi notunun cümlesini yaz"],minimum:["Laf sokmadan cumartesi uygun olduğunu yazıp gönder","Gönüllü ekibin bilgi notuna kullanılabilir bir cümle yaz"],cue:["Gönüllü sorumlusuna yanıt vermeden önce","Öğle yemeğinden sonra, bilgi notunu yazmadan önce"],place:["Gönüllü sorumlusuyla mesajlaştığımız ekranda","Mutfaktaki yazı masasında"],minutes:[2,1,3],fallback:["Dilekleri atla; uygun olduğun günü açıkça yazıp gönder","Ara ver; korunmayı veya destek almayı seç"],observation:["Uygun olduğum günü bildirdim mi; yanıt geldi mi","Dileklerin bana uygun gelip gelmediği"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sorumluya yalnızca cumartesi görev alabileceğini söyle",minimum:"Laf sokmadan cumartesi uygun olduğunu yazıp gönder",minutes:2,cueHint:"Gönüllü sorumlusuna yanıt vermeden önce",placeHint:"Gönüllü sorumlusuyla mesajlaştığımız ekranda",obstacleHint:"Dilek canımı yakıyor veya zoraki geliyor",fallbackHint:"Dilekleri atla; uygun olduğun günü açıkça yazıp gönder",observationHint:"Uygun olduğum günü bildirdim mi; yanıt geldi mi"},stopRule:"Sıkıntı veren dilekleri bırak. Çevrene odaklan veya destek al. Sınırlarını koru, güvenli olmayan iletişimden kaçın.",accessibleAlternative:"Gözlerin açık kalsın. Güvenli bir kişiyi, nötr sözleri veya hiç dilek söylememeyi seç."},result:{question:"Açık cümleni kullandın mı veya seçtiğin adımı attın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-5-decision",scenario:"Leyla’nın güvenle konuşabildiği gönüllü sorumlusu pazar günü çalışma istiyor. Leyla pazar görev alamaz. Taslağında iğneleyen bir söz var, hâlâ kızgın hissediyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-5-delay",text:"İyi dilek kızgınlığını değiştirene kadar hazırladığı yanıtı bir süre bekletsin.",feedback:"Bilgi eksikse beklemek yardımcı olabilir. Burada Leyla’nın uygun olduğu gün belli. İçinin ısınmasını beklemeden iğneleyen sözü çıkarıp sınırını açıkça yazıp gönderebilir. Kızgınlık önce geçmek zorunda değil."},{id:"meditation-5-accept",text:"Pazar sınırını iyice belli edeceğini düşünerek iğneleyen sözü olan yanıtı göndersin.",feedback:"Sınırının ciddiye alınmasını istemesi, laf sokmayı çekici kılıyor. Oysa uygun olduğu günü açıkça söylemek sınırı zaten iletiyor. Ek eleştiri, korumak istediği sınırın önüne geçebilir."},{id:"meditation-5-send",text:"İğneleyen sözü çıkarsın, hangi gün uygun olduğunu açıkça yazıp şimdi göndersin.",feedback:"Bu seçim, duyguyu ön şart yapmadan kararlaştırdığı işi günlük hayata taşıyor. İsterse iyi bir dilek de sunabilir. Ne yaptığına dair kanıt, gerçekten gönderdiği cümledir."}],bestOptionId:"meditation-5-send"}},carry:{takeaway:"İsteğe bağlı bir dilek, açık bir adıma eşlik edebilir. Sınırından vazgeçmeni istemez.",followUp:{questionId:"meditation-5-return",question:"Kullandığın cümle asıl bilgiyi korudu mu? Gereksiz iğneleyici sözü çıkardın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Olumlu duygu başka bir sonuçtur",paragraphs:["Zeng ve arkadaşları, 1.759 kişiyi kapsayan yirmi dört raporu derledi. Günlük olumlu duygu tahminine, bekleme listesiyle yapılan sekiz rastgele karşılaştırma katkı verdi. Birleştirilmiş 0,395 ve 0,392 değerleri, aynı deneydeki uyarılma düzeyine ilişkin alternatif ölçümlerden birini seçerek hesaplandı. Aynı sonucun iki tahminidirler. Enerjik ve sakin duygular üzerindeki ayrı etkiler değildirler. Etkin karşılaştırma kullanan çalışma azdı. Bu yüzden sonucu, bugün söyleyeceğin tek dileğe eşit tutma. (meditation-M09)","Başka bir erken atölyede, yedi haftaya yayılan eğitmenle altı seans ve evde dinlenen kayıtlar vardı. Olumlu duygulardaki haftalık değişim, çalışmayı bitiren 139 kişide gruplar arasında istatistiksel olarak anlamlı biçimde farklıydı. Başlangıçta atanan gruba göre ve protokole uyanlarla yapılan analizlerde ise anlamlı değildi. Dışlanan kişiler ve bekleme listesiyle karşılaştırma, çıkarımı sınırlar. Yazmadan önceki kısa dilek o atölye değildir. İki makale de dileklerin daha iyiliksever davranmanı sağladığını, bu ilişkiyi iyileştirdiğini veya örnekteki açık yanıta neden olduğunu göstermez. (meditation-M11)"]},{heading:"Niyet, seçim ve sınırlar",paragraphs:["Salzberg’in yazar sayfası, iyi dilek geleneğinin kaynağını gösterir ve kısa dilek örnekleri verir. Tam bir metin sunmaz; her cümleyi ve dilek yöneltilen kişilerin sırasını doğrulamaz. Bugünkü özgün sözler, güvenli kişi seçimi ve kısaltılmış uygulama ODA uyarlamalarıdır. Eğitmenin tam yöntemi değildir. Zor bir kişiyi seçmek isteğe bağlıdır. Dersi bitirmek için hiçbir zaman zorunlu tutulmaz. Buna göre bir kişiyi atlayabilir veya başka güvenli kişiyi seçebilirsin. (meditation-M18)","Niyet ile duygu arasındaki ayrımı koru. İçin ısınmadan dilek sunabilir, kendin yerine güvenli birini seçebilir, uygulamayı atlayabilir veya sıkıntı veriyorsa durabilirsin. Bu seçimler sınırının geçerli olup olmadığını belirlemez. Kullandığın cümleye bak: hangi bilgi gerekliydi, hangi söz laf sokuyordu, ardından nasıl bir yanıt geldi? Ruh hâlin değişmediyse veya mesajın yanıtsız kaldıysa bunu da olduğu gibi kaydet. Önceki odağın daha uygunsa onu kullan. Kurs boyunca denediğin şey, kendi seçtiğin işe yarayan adım olarak kalsın."]}],sourceIds:["meditation-M09","meditation-M11","meditation-M18"]}},{schemaVersion:2,revision:2,id:"meditation-6",courseId:"meditation",locale:"tr",title:"Yine sert tepki mi? Bir sonraki yanıtını prova et.",goal:"Tanıdık bir durum işi aksatıyorsa tek bir davranış hazırla. O an geldiğinde kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine mi sert mesajı gönderdin? O an kullanacağın cümleyi önceden prova et.",reason:{id:"meditation-6-reason",label:"Son tepkin neye mal oldu? Hangi davranışını değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Sonra düzeltmem gereken sözler gönderdim","İşe yarayan bir fırsatı kaçırdım","Çözülmemiş ayrıntıyı belirsiz bıraktım","Önceki bir denemem yok"]},why:{id:"meditation-6-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Zihinde prova araştırması, iş ve becerilerle ilgili. Yeni bir kişilik yaratmakla değil. Otuz yedi çalışmada, yayın yanlılığına göre düzeltilen ortalama performans ilişkisi küçüktü. Duygusal teslimiyeti, düşünceyle iyileşmeyi veya üç kez tekrar etme şartını doğrulamadı.","Notlarında belirli bir durumun seçtiğin yararlı adımı engellediğini görüyorsan prova yap. O anı ve kontrolündeki tek davranışı belirle. İstersen bir kez gözünde canlandır veya hiç görüntü kurmadan cümleyi yaz. Sonra gerçek, güvenli bir fırsatta kullan. Hazırlık tek başına hazırlık kalır. O an hiç gelmezse fırsat oluşmadığını kaydet. Olmamış başarıyı yazmak veya daha sakin hissetmek zorunda değilsin."],example:{title:"Leyla geciken bilgi için soru hazırlıyor",text:"Leyla saat 09.00’da “Hâlâ ne eksik?” diye yazıyor. Çünkü geciken bilgi notları onu sık sık sert yanıta sürüklüyor. Soruyu sorduğunu kısaca hayal ediyor, ardından öğlenki konuşmada bu soruyu sormayı eylem olarak planına kaydediyor. Not gecikiyor. Soruyu sorunca bir ayrıntının çözülmediğini öğreniyor. Sorduğu soruyu kaydediyor. Kişiliğinin değiştiğini veya toplantının pürüzsüz geçtiğini söylemiyor."}},move:{invitation:"Seçtiğin işi koru. Geciken bilgi notu örneğini kendine göre düzenle.",instructions:["Kaydetmeden önce gerçek fırsatı belirle. İsteğe bağlı prova hazırlık olarak kalır.","Seçtiğin davranışı o anda kullan. Yazı yazmayı konuşmaya çevirmen gerekmez."],prompts:[],suggestions:{action:["Gönüllü sorumlusuna hâlâ neyin eksik olduğunu sor","Bilgi notuna sıradaki doğru bilgiyi anlatan cümleyi yaz"],minimum:["Hâlâ neyin eksik olduğunu sor","Bilgi notuna doğru bilgiyi anlatan bir cümle yaz"],cue:["Gönüllü ekibin bilgi notu geç geldiğinde","Gönüllü ekibin yarım kalan bilgi notunu açtığımda"],place:["Gönüllü sorumlusuyla mesajlaştığımız ekranda","Mutfaktaki yazı masasında"],minutes:[2,1,3],fallback:["“Hâlâ ne eksik?” sorusunu yazıyla ilet","Sonraki gerçek ve uygun fırsatı seç"],observation:["Gecikme, sorduğum soru ve gelen yanıt veya sessizlik","Seçtiğim davranıştan sonra ne olduğu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Gönüllü sorumlusuna hâlâ neyin eksik olduğunu sor",minimum:"Hâlâ neyin eksik olduğunu sor",minutes:2,cueHint:"Gönüllü ekibin bilgi notu geç geldiğinde",placeHint:"Gönüllü sorumlusuyla mesajlaştığımız ekranda",obstacleHint:"Cümleyi hatırlamadan o durumla karşılaşıyorum",fallbackHint:"“Hâlâ ne eksik?” sorusunu yazıyla ilet",observationHint:"Gecikme, sorduğum soru ve gelen yanıt veya sessizlik"},stopRule:"Ortam güvenli değilse veya sıkıntı artarsa ara ver. Korunmayı, desteği veya çevrende bir şeye odaklanmayı seç.",accessibleAlternative:"Kaydetmeden önce ne yapacağını ve hangi anda kullanacağını belirle. Yazı, işaret dili ve hayal etmeden denemek geçerli."},result:{question:"Hazırladığın davranışı, fırsat gerçekten geldiğinde günlük hayatta kullandın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-6-decision",scenario:"Leyla sorusunu biliyor. Gönüllü sorumlusuyla güvenli bir konuşma fırsatı var. Bilgi notu geç geliyor; Leyla kızgın hissediyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-6-ideal",text:"Soruyu sorup sormamaya karar vermeden önce konuşmanın bütünüyle pürüzsüz geçtiğini hayal etsin.",feedback:"Pürüzsüz bir sahne güven verebilir. Ama şimdi oluşan fırsattan uzaklaştırıyor. Kullanabileceği bir soru ve güvenli bir fırsat var. Soruyu sorup gelen yanıtı kaydedebilir."},{id:"meditation-6-ask",text:"Geciken notu fark etsin. Başka yorum yapmadan önce hazırladığı soruyu sorsun.",feedback:"Bu seçim, o ana bağlı gerçek davranışı deniyor. Kızgınlık sürebilir. Prova hazırlıktı. Soruyu sormak ve yanıtı kaydetmek, günlük hayatta ne yaptığına dair kanıt sağlar."},{id:"meditation-6-rehearse",text:"Soruyu tamamen rahat söyleyebilmek için kullanmadan önce birkaç kez daha prova etsin.",feedback:"Gerçek bir beceri eksiği varsa daha çok prova yardımcı olabilir. Burada soru hazır. Ek hazırlık fırsatı kaçırmasına yol açabilir. Hislerin tamamen yatışmasını şart koşmadan bir kez sor."}],bestOptionId:"meditation-6-ask"}},carry:{takeaway:"Kullanabileceğin tek bir davranışı prova et. Sonra gerçekten kullanıp kullanmadığını kaydet.",followUp:{questionId:"meditation-6-return",question:"O an geldi mi? Yalnızca prova mı ettin, yoksa seçtiğin davranışı kullandın mı?",observationPrompt:"Notlarına bak: Gerçekte ne yaptın? Hangi kısım yalnızca plan olarak kaldı?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"İş provası için kanıt daha sınırlı",paragraphs:["Toth ve arkadaşlarının üniversitede yayımlanan özeti, 1995 ile 2018 arasında çıkan, zihinde provaya ilişkin otuz yedi çalışma bildiriyor. Yayın yanlılığına göre düzeltilen performans ilişkisi küçüktü: r = 0,131. Özet, tam yöntemleri, toplam katılımcı sayısını veya güven aralığını vermiyor. Daha eski karşılaştırmayı veya toplam etki sayısını da doğrulamıyor. Araştırmanın sınırını değerlendirirken erişilen bu bilgiyle yetinmek gerekir. (meditation-M13)","Bu kanıt iş ve becerilerle ilgili. Kişilik değişimini, duygusal boşalmayı veya iyileşmeyi göstermez. Bugünkü belirli fırsatı, soruyu veya isteğe bağlı tek provayı da sınamaz. Bir davranışı yazmak veya hayal etmek hazırlık olarak kaydedilebilir. Sonraki gerçek davranışın kendi denemesi ve sonucu vardır. Bunları ayrı tut ki başarılı prova, gerçekleşmemiş bir konuşmanın yerine geçmesin. Belirli bir duygu veya tekrar sayısı şart değil. Soruyu rahatça prova etmiş olmak, onu karşındaki kişiye sorduğun anlamına gelmez."]},{heading:"Değişmiş hissetmeyi beklemeden davranışını planla",paragraphs:["Gollwitzer ve Sheeran’ın hedef planlama derlemesi, farklı alanlarda tanınabilir bir durumu yapılabilir bir davranışla eşleştirmeyi destekler. Birleşik her prova düzenini doğrulamaz. “Not gecikirse neyin eksik olduğunu soracağım”, kontrolünde olan bir işi söyler. “Sakin bir lider olacağım” belirli bir işi söylemez. Buradaki zaman ve söz seçimi ODA’ya aittir. Kendi denemende de fırsatı ve kullanacağın cümleyi açıkça belirt. (meditation-M05)","Dispenza’nın yayınevinin içindekiler sayfası, dört haftalık programın aşamalarını gösteriyor. Kitabın içeriği incelenmedi ve bu birleşik programın kontrollü doğrulaması bulunmadı. Planlama ve iş provası bulguları onun teslimiyet, kuantum, genetik veya iyileşme iddialarını kanıtlayamaz. Değişmiş hissetmeyi beklemek yerine güvenli fırsatı, cümleyi denemek için kullan. Gözlenebilir bir davranış seç. Duyguların sürebilir. Gerçekte yaptığının sonucuna bak; gerekirse yol açtığın sorunu düzelt. Sana önerilen tedaviyi sürdür. (meditation-M20)"]}],sourceIds:["meditation-M13","meditation-M05","meditation-M20"]}},{schemaVersion:2,revision:2,id:"meditation-7",courseId:"meditation",locale:"tr",title:"Gününe gerçekten uyan denemeyi koru",goal:"Dikkatini geri getirdiğin ve iş yaptığın kayıtları gözden geçir. Yapılabilir sürümü koru, sonraki denemenin gününü belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dersler hoşuna gitti ama düzen dağıldı mı? Gelecek hafta için gerçekten denediğin yöntemi seç.",reason:{id:"meditation-7-reason",label:"Gelecek hafta neyi koruyacak, küçültecek veya bırakacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Kütüphaneye varınca başlamayı sürdürmek","Arayı kısaltıp işi korumak","Sıkıntı veren uygulamayı bırakmak","Kayıt yok; ilk işi seçmek"]},why:{id:"meditation-7-why",label:"Bu adım bu hafta hayatında neye yer açar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı koşullarda tekrar edilen davranış zamanla daha otomatik olabilir. Ama alışkanlık süresi değişir. Gözlemsel bir çalışma, meditasyonu değil günlük davranışları izledi. Modellerdeki süreler, uygulaman için yirmi bir veya altmış altı günlük bitiş tarihi belirlemiyor.","Sürdürdüğün denemeyi gözden geçir. Hangi başlama anları oluştu? Hangi odakları rahatsız olmadan kullanabildin? Ardından hangi yararlı adımları attın? Kaydın desteklediği bir sürümü koru. Kayıt yoksa ilk denemeyi planla. Gelecek hafta üç uygun fırsat seç. Bu, kursun önerisi; zorunlu uygulama süresi değil. İlkinden başla, her birini ayrı kaydet. Destek almak, dinlenmek veya bırakmak da uygun karar olabilir."],example:{title:"Leyla kendine uyan anı koruyor",text:"Leyla pazar günü üç kayda bakıyor. Mutfakta bir kez denemiş. Kütüphaneye iki gelişinde de ardından bilgi notuna bir cümle yazmış. Kütüphaneye geliş anını koruyup pazartesi kısa bir deneme planlıyor. Pazartesi odadaki sese dönüyor ve bir cümle yazıyor. Huzurlu değil, telaşlı hissediyor. Bunu kaydediyor. Sonraki günleri şimdiden yapılmış saymıyor."}},move:{invitation:"Seçtiğin işi koru. Havlu katlama örneğini kendine göre düzenle.",instructions:["Kayıtlı işini, en küçük adımı, başlama anını, yeri koru. Yoksa örnek veya ilk işini seç.","Planı değiştirdiysen kaydetmeden önce yeni başlama anını belirle.","Destek, dinlenme veya başka işi kendi en küçük adımına göre kaydet."],prompts:[],suggestions:{action:["Odadaki seslere dön; bir havlu katla","Yeniden odaklan; gönüllü ekibin bilgilendirmesini sonuna kadar dinle"],minimum:["Dikkatini bir kez geri getirip bir havlu katla","Konuşan kişi bilgi vermeyi bitirene kadar dinle"],cue:["Öğle yemeğinin bulaşıkları kaldırıldıktan sonra","Gönüllü ekibin kısa toplantısı başladığında"],place:["Mutfak masasında","Rahatça erişebildiğim gönüllü ekip toplantı masasında"],minutes:[2,1,3],fallback:["Uygun başlama anını seç; rahat kullandığın odağı koru","Yeni deneme planlamadan ara ver"],observation:["Başlama anı, dikkatimi geri getirmem ve katladığım havlu","Bilgilendirmeyi dinledim mi; konuşanın sözünü kestim mi"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Odadaki seslere dön; bir havlu katla",minimum:"Dikkatini bir kez geri getirip bir havlu katla",minutes:2,cueHint:"Öğle yemeğinin bulaşıkları kaldırıldıktan sonra",placeHint:"Mutfak masasında",obstacleHint:"Öğle yemeği sonrası başlama anı artık haftama uymuyor",fallbackHint:"Uygun başlama anını seç; rahat kullandığın odağı koru",observationHint:"Başlama anı, dikkatimi geri getirmem ve katladığım havlu"},stopRule:"Sıkıntı, baş dönmesi veya gerçeklikten kopma hissinde dur. Tekrarlayan kaygılandırıcı durumlar için yetkin bir uzmandan yardım al. Sağlık hizmetini geciktirme.",accessibleAlternative:"Çevrene odaklan, oturarak veya hareket etmeden dene. Başlama anını değiştirdiysen kaydetmeden önce belirle. Yardım için “Bunu uyarla”, ardından “Destek” seç. İsteğini ve en küçük adımını belirt."},result:{question:"Sonraki kısa sürümü veya seçtiğin destek adımını gerçekten denedin mi?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin işi yapmanın önüne ne çıktı?"},judgment:{primary:{id:"meditation-7-decision",scenario:"Leyla’nın kayıtlarında sabahların sıkışık olduğu, kütüphaneye iki gelişinde denemenin yürüdüğü görünüyor. Gelecek hafta aynı bilgi notuna dikkatini vermek istiyor.",question:"Bu denemeye hangi seçim uyuyor?",options:[{id:"meditation-7-restore",text:"İlk düzeni hakkıyla denemek için gelecek hafta daha uzun sabah seanslarına zaman ayırsın.",feedback:"Koşullar değiştiyse daha uzun deneme uyabilir. Ama kayıtlar şimdi sabahların sıkışık olduğunu gösteriyor. Pek oluşmayan planı büyütmeden önce gördüğün kütüphane fırsatını kullan. İlk düzeni korumak şart değil."},{id:"meditation-7-rotate",text:"İlgisini yeniden canlandıracak yöntemi bulmak için gelecek hafta her gün başka teknik seçsin.",feedback:"Araştırmak yararlı olabilir. Ama kayıtlar kullanılabilir bir odağı ve oluşan fırsatı zaten gösteriyor. Her şeyi değiştirmek, nerede takıldığını anlamayı zorlaştırır. Önce elindeki denemeye bak."},{id:"meditation-7-keep",text:"Kütüphaneye geliş anını ve rahat kullanabildiği odağı korusun. Bir sonraki cümleyi ne zaman yazacağını planlasın.",feedback:"Bu seçim, gerçek denemelerden yararlanıp yapılabilir sonraki sürümü seçiyor. Daha sonraki fırsatlar denenene kadar plan kalır. Her kayda ayrı bak. Sakinlik veya kusursuz bir hafta şart değil."}],bestOptionId:"meditation-7-keep"}},carry:{takeaway:"Rahatça kullanabildiğin odağa geri dön, işe yarayan adımı at. Gelecek haftaya kayıtların yön versin.",followUp:{questionId:"meditation-7-return",question:"Seçtiğin işte veya destek isteğinde gerçekte ne oldu? Bir sonraki uygun fırsatta neyi değiştirmek gerekiyor?",observationPrompt:"Ne yapıldı? Hangi yanıt veya sonraki adım hâlâ bekliyor?",adjustmentPrompt:"Bir sonraki fırsatta neyi koruyacak, neyi değiştireceksin?"}},goDeeper:{sections:[{heading:"Bir hafta, gözden geçirme aralığıdır",paragraphs:["Lally ve arkadaşları, doksan altı gönüllüyü seksen dört gün izledi. Katılımcılar tekrarlanan koşullarda yeme, içme veya hareket davranışlarını sürdürüyordu. Seksen iki kişi yeterli veri sağladı. Otuz dokuz kişinin otomatiklik modeli uygun bulundu. Tahmini süreler çok değişkendi ve kısmen gözlem süresinin ötesine uzanıyordu. Ortanca altmış altı günlük tahmin bir model sonucu. Alışkanlığın tamamlanma tarihi veya meditasyona ilişkin bulgu değil. Bu yüzden kendi uygulaman için bir son tarih olarak kullanma. (meditation-M14)","Kaçırılan fırsatlara ilişkin gözlemsel analiz, tek bir fırsattan sonra otomatiklikte istatistiksel olarak anlamlı düşüş bulmadı. Ama bu aksamalar rastgele belirlenmedi. Gelecekteki her kaçırmanın ne anlama geldiğini garanti edemez. ODA’nın üç uygun fırsatı ve haftalık değerlendirmesi birer tasarım seçimi. Başlama anı, adımın boyutu ve ortamın hayatına uyup uymadığını görmek için kullan. İlerideki tarih, yapılmış deneme değildir. Sonraki planı değiştirirken eski kayıtları koru. Bir sonraki denemenin en küçük adımını değiştirmen, önceki sözünü değiştirmez."]},{heading:"Devam planında durmaya da yer var",paragraphs:["NCCIH, sağlık hizmetinin yerine meditasyon koymamayı ve değerlendirmeyi geciktirmemeyi önerir. Zararlara ilişkin araştırmanın sınırlı olduğunu belirtir. Farias ve arkadaşlarının derlemesinde, gözlemsel raporlar ve deneyler dâhil birbirinden farklı seksen üç çalışma vardı. Birleştirilmiş %8,3 olumsuz deneyim tahmini, sonraki kısa uygulama seansının olasılığı değildir. Tanımlar, süreler ve deneyimleri saptama yolları oldukça farklıydı. Zor deneyimler, uygulamanın işe yaradığının kanıtı değil. Böyle bir deneyimi ilerleme işareti sayıp sürdürmen gerekmez. (meditation-M03; meditation-M04)","Hangi odağı korursan koru, durmak için de yolun olsun. Gözleri açık tutmak, kısa süre, çevreye odaklanmak veya oturmak önlemdir; garanti değil. Tekrarlayan sıkıntı veya gerçeklikten kopma kaygısı, yetkin bir ruh sağlığı uzmanının desteğini gerektirir. Meditasyon eğitmeni değerlendirme yerine geçmez. Dinlenme planı veya yardım isteği hayatına yeni bir seanstan daha iyi hizmet edebilir. Devam eden deneme, sana uygunluğu ve işe yarayan adımı sınar. Belirtileri iyileştirmeyi, sürekli sakinliği, kusursuz katılımı veya bütün teknikleri deneme borcunu değil."]}],sourceIds:["meditation-M14","meditation-M03","meditation-M04"]}}],n=[{id:"meditation-1",practice:["Bir dakika gibi, seçtiğin kısa bir süre güvenle otur. Zamanlayıcı isteğe bağlı.","Olağan nefes hislerini, gözlerin açıkken bir sesi veya gördüğün bir nesneyi seç.","Daldığını fark edince bir kez geri dön. Sıkıntı, baş dönmesi veya gerçeklikten kopma hissi artarsa dur."],reflection:"Dikkatin en çok nereye gitti? Geri dönmek nasıl geldi?",question:"Otururken dikkatin sürekli dağılıyorsa bu ne anlama gelir?",options:["Meditasyon bana göre değil; bırakmalıyım.","Daldığımı fark edip geri dönmek, alıştırmanın kendisi.","Zihnim tamamen boşalana kadar kendimi daha çok zorlamalıyım."],correct:1,feedback:"Zihnin dalabilir. Bilinçli farkındalık meditasyonunda amaç düşüncesiz bir zihin değil. Daldığını fark edip zorlamadan geri gelme becerisini deniyorsun.",photo:{id:"1758273240112-c7724c9bb4a5",alt:"Evde, yerde oturup gözleri kapalı meditasyon yapan genç bir kadın"}},{id:"meditation-2",practice:["Rahatça otur veya uzan. Yapabileceğin kısa bir süre seç. İstersen gözlerin açık kalsın.","İstersen rahat temas noktalarını fark et. Rahatsız bölgeleri atla veya dikkatini çevrene ver.","Gerçekte ne fark ettiğini söyle. Gerekliyse işine yarayan bir düzenleme yap. Sıkıntı artarsa dur."],reflection:"Bedeninin hangi bölümünü fark etmek sana yeni veya şaşırtıcı geldi?",question:"Beden taramasında bir bölgede hiçbir şey hissetmezsen ne yaparsın?",options:["Bir his gelene kadar o bölgeyi kasar veya hareket ettiririm.","“Burada belirgin bir his fark etmedim” deyip ilerlerim.","Yanlış yaptığımı düşünüp baştan başlarım."],correct:1,feedback:"Belirgin bir his fark etmemek, dikkatine ilişkin gözlemdir. Uyuşma teşhisi değildir. Hisleri zorlama. Yeni başlayan veya süren kaygılandırıcı belirtiler için tıbbi değerlendirme gerekir.",photo:{id:"1535987271305-c26a8935f74a",alt:"Güneş altında çimlere uzanmış dinlenen bir kadın"}},{id:"meditation-3",practice:["Dikkatini bir söze vermek istiyorsan sana uygun kısa kelime, ses, cümle veya özel dua seç.","Seçtiğin kısa süre rahat otur. İstersen gözlerin açık kalsın; nefesin doğal olsun.","Düşünceler araya girince kelimene dön. Rahatsızlık artarsa dur veya çevrene yönel."],reflection:"Seçtiğin kelime sana nasıl geldi? Yarın aynısını kullanacak mısın?",question:"Benson’ın yönteminde düşünceler araya girince ne yaparsın?",options:["Düşünceyi itip zihnimi boşaltırım.","Ortada bırakırım. Bu, odaklanamadığım anlamına gelir.","Zorlamadan düşünceyi fark edip kelimeme geri dönerim."],correct:2,feedback:"Uygulayıcı rehberi, zorlamadan geri dönmeyi anlatır. Belirli bir cümle, nefes düzeni veya aynı kelimeyi bir hafta kullanma şartı koymaz. Sıkıntı artarsa dur veya uyarla.",photo:{id:"1513097847644-f00cfe868607",alt:"Güneşli bir günde ahşap iskelede sessizce oturan bir kadın"}},{id:"meditation-4",practice:["Güvenli ve tanıdık bir yol seç. İstersen oturarak, yerinde dururken teması kullan.","Gözlerin açık, tehlikeler öncelikli olsun. Doğal nefes al. Rahat adım eşleştirmesi isteğe bağlı.","Seçtiğin kısa sürede güvenli temasları veya çevreni fark et. Güvenlik dikkat gerektirince saymayı bırak."],reflection:"Yavaş yürürken daha önce fark etmediğin ne gördün veya duydun?",question:"Yürüyüş meditasyonunda adım sayısı nasıl seçilir?",options:["Herkes için sabittir: her nefeste dört adım.","Kendi nefes ritmime ve yürüme hızıma göre ayarlarım.","Amaç olabildiğince çok adım atmak."],correct:1,feedback:"İsteğe bağlı adım eşleştirmesi, rahat ve doğal ritmi izler. Gözlerin açık, çevren öncelikli olsun. Bu rehber sabit oranı veya tek başına sağlık etkisini kanıtlamaz.",photo:{id:"1477332552946-cfb384aeaf1c",alt:"Güneşli bir yolda yavaşça yürüyen bir kadın"}},{id:"meditation-5",practice:["Kendin veya güvenli, sevdiğin biri için uygun kısa dilekler seç. Sözler ODA uyarlaması.","İçin ısınmak zorunda değil. Kendi isteğinle dilek sun. Rahatsız ediyorsa kişileri atla veya çevrene yönel.","Zor bir kişi isteğe bağlı, hiçbir zaman gerekli değil. Sıkıntıda dur. Sınırlarını koru, güvensiz iletişimden kaçın."],reflection:"İyi dileklerini kime yöneltmek en kolaydı? Kime en zordu?",question:"Metta sırasında sıcak bir duygu hissetmiyorsan ne yaparsın?",options:["Yöntemin bana uymadığına karar verip bırakmayı seçerim.","Duyguyu zorla ortaya çıkarmaya çalışırım.","Rahatsız etmiyorsa sıcak duygu şart koşmadan kendi isteğimle sürdürebilirim."],correct:2,feedback:"İsteğe bağlı dilek için sıcak duygu şart değil. Sıkıntıya rağmen devam etmek de şart değil. Kişiyi değiştirebilir, çevrene yönelebilir veya durabilirsin. Dilekler affetmeyi veya iletişim kurmayı gerektirmez.",photo:{id:"1604881991720-f91add269bed",alt:"Masanın iki yanından birbirinin elini şefkatle tutan iki kişi"}},{id:"meditation-6",practice:["Tekrarlayan belirli bir durumu, gelen düşünceyi ve değiştirmek istediğin davranışı belirle.","İstersen güvenli bir sahnede yapılabilir tek davranışı yaz veya hayal et. Bu hazırlık; kişilik değişimi değil.","Gerçek davranışı ve anını seç: “Bu olursa şunu yapacağım.” Gerçek denemeyi ayrı kaydet."],reflection:"Eski tepkin devreye girdiği anda olmak istediğin kişi neyi farklı yapardı?",question:"Bu tekniğin hangi bölümü araştırmayla en iyi destekleniyor?",options:["Kuantum alanıyla olayları ve gerçekliği değiştirmek.","İstediğim davranışı zihnimde prova edip sonra günlük hayatta denemek.","İlaç gerekmeyecek biçimde düşünceyle hastalığı iyileştirmek."],correct:1,feedback:"Araştırma, iş ve beceri performansında küçük ortalama faydalarla ilgili. Kendini yeniden yaratma alıştırmasını veya gerçek deneme eklemenin üstünlüğünü doğrulamaz. Sağlık hizmetini sürdür. Kuantum ve iyileşme iddiaları desteklenmiyor.",photo:{id:"1631832293782-2eda7804489b",alt:"Penceresinden sabah güneşi giren, pencere önünde saksı bitkisi bulunan sessiz bir oda"}},{id:"meditation-7",practice:["Hayatına uyan bir uygulama için tanıyabileceğin başlama anı ve güvenli yer seç.","Rahatsız etmeden kullanabildiğin kısa sürümü seç, sonraki denemenin gününü belirle. Denemeleri olduktan sonra kaydet.","Çevreye odaklanma, oturma veya hareketsiz seçeneğe uygun yedek plan yaz. Gerekirse durma ve destek de olsun."],reflection:"Bu kursta sana en çok hangi teknik yardım etti? Neden?",question:"Meditasyonda sıkıntın belirgin artıyor, eski anılar seni sarsıyorsa ne yapmalısın?",options:["Durur, gözlerimi açar, ayaklarımı hisseder ve bir uzmandan destek alırım.","Daha uzun oturur, hislerin kendiliğinden geçmesini beklerim.","Bunu meditasyonun iyi gittiğinin işareti sayıp zorlamayı sürdürürüm."],correct:0,feedback:"Zor deneyimler olabilir. Ama derlemedeki toplu yüzde, kısa seansındaki kişisel riskin değil. Sıkıntı artarsa dur. Tekrarlayan kaygılandırıcı durumlarda yetkin destek al. Sağlık hizmetini veya acil yardımı geciktirme.",photo:{id:"1781255575628-d645cc39160f",alt:"Ahşap zeminde renkli yer minderleri ve örgü pufları olan sade bir köşe"}}],l={id:"meditation",title:"Aklın yine mi dağıldı? Önem verdiğin şeye dön.",subtitle:"Yedi kısa ders. Rahat bir odak dene, ardından dikkatini bir işte veya konuşmada kullan.",description:"Kendi hayatındaki işe yarayan tek bir adım için, kendi isteğinle dikkatini geri getirmeyi dene. Başka bir odağı ancak gerçek bir güçlüğüne karşılık geliyorsa kullan. Ne olduğuna bak, sana uyan sürümü koru.",scope:"Yetişkinler için meditasyon eğitimi. Tanı veya tedavi değildir; terapinin veya ilacın yerini tutmaz. Hekimine danışmadan sana önerilen tedaviyi değiştirme. Travma, psikoz veya yoğun sıkıntıda planını yetkin bir ruh sağlığı uzmanıyla yap. Eğitmen, değerlendirme yerine geçmez. Gerektiğinde gözlerini açık tut, çevrende bir şeye odaklan veya ara ver. Sıkıntı, baş dönmesi veya gerçeklikten kopma hissi artarsa dur. Süren, tekrarlayan veya kaygılandıran belirtilerde destek al. Araç kullanırken uygulama yapma. Yeni başlayan veya süren ağrı, uyuşma ya da kaygılandıran diğer belirtiler için tıbbi değerlendirme al. Kendine zarar verme düşüncelerinde gecikmeden uzman veya kriz desteği al. Acil tehlikede yerel acil yardıma ulaş.",outcome:"Seçtiğin dikkat ve eylem planı, dürüst deneme kayıtları. Gelecek hafta için sana uyan bir sürüm; ne zaman duracağın ve nasıl destek alacağın açık.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"Bir bankta sessizce oturup dağ manzarasına bakan bir kadın"},lang:"tr",lessons:i.map((a,e)=>({...n[e],schemaVersion:2,v2:a,title:a.title,goal:a.goal,minutes:a.minutes.learning,reading:a.idea.paragraphs,example:a.idea.example,deeper:a.goDeeper.sections,sources:[...new Set([...a.goDeeper.sourceIds,"meditation-M03"])],takeaway:a.carry.takeaway,visual:{kind:"steps",title:"Aynı denemeyi sürdür",steps:[{label:"Başlama anı",text:"Sana uyan bir fırsat seç."},{label:"Adım",text:"İşe yarayan en küçük adımı dene."},{label:"Geri bak",text:"Ne olduğunu kaydet, sonraki denemeyi seç."}]}}))};export{l as COURSE,i as MEDITATION_LESSONS_V2,r as SOURCES};
